"""Block parsing and document-wide reference collection."""
import html
import re
from .model import Document

REF = re.compile(r'^ {0,3}\[([^\]]+)\]:[ \t]*(<[^>]*>|[^\s]+)(?:[ \t]+(?:"([^\"]*)"|\'([^\']*)\'|\(([^)]*)\)))?[ \t]*$')
