def parse_inlines(document: Document) -> Document:
    def walk(blocks):
        for b in blocks:
            t=b['type']
            if t in ('paragraph','heading'): b['html']=inline(b['text'], document.references)
            if t in ('quote',): walk(b['children'])
            if t=='list':
                for item in b['items']: walk(item)
